  });
});

test('a task can be a command string', () => {
  validateTask('lint', 'node scripts/lint.js --fix');
  assert.throws(() => validateTask('x', ''), TaskError);
  assert.throws(() => validateTask('x', '   '), TaskError);
  assert.throws(() => validateTask('x', ['node', 'a.js']), TaskError);
});

test('a command string is split on spaces, and "node" means this node', () => {
  assert.deepStrictEqual(commandFor('node scripts/lint.js --fix'), {
    file: process.execPath,
    args: ['scripts/lint.js', '--fix'],
  });
  assert.deepStrictEqual(commandFor('  git  status '), { file: 'git', args: ['status'] });
  assert.deepStrictEqual(commandFor('node my\\ dir/a.js'), {
    file: process.execPath,
    args: ['my dir/a.js'],
  });
});

test('runTask resolves to the exit code', async () => {
  assert.strictEqual(await runTask({ script: 'scripts/hello.js' }, { stdio: 'ignore' }), 0);
});

test('runTask runs a command string', async () => {
  assert.strictEqual(await runTask('node scripts/hello.js', { stdio: 'ignore' }), 0);
  assert.strictEqual(await runTask('node -e process.exit(3)', { stdio: 'ignore' }), 3);
});
